  Code.f_snippets__org_patternfly_showcase_Code_.put('progress-helper-text', 'Tuples<Status, String> status = tuples(\n        tuple(info, \"Default variant\"),\n        tuple(success, \"Success variant\"),\n        tuple(warning, \"Warning variant\"),\n        tuple(danger, \"Danger variant\")\n);\nProgress progress = progress();\nHelperText helperText = helperText(\"Default variant is being displayed\");\n\nreturn div()\n        .run(div -> {\n            for (Tuple<Status, String> tuple : status) {\n                div.add(radio(Id.build(\"progress-helper-text\", tuple.key.name()),\n                        \"progress-helper-text-status\",\n                        tuple.value)\n                        .value(tuple.key == info)\n                        .onChange((event, component, value) -> {\n                            progress.status(tuple.key);\n                            helperText.firstItem().text(tuple.value + \" is being displayed\");\n                        }));\n            }\n        })\n        .add(br())\n        .add(progress\n                .title(\"Title\")\n                .value(33)\n                .addHelperText(helperText))\n        .element();');
  Code.f_snippets__org_patternfly_showcase_Code_.put('progress-stepper-basic', 'div()\n        .add(progressStepper()\n                .ariaLabel(\"Basic progress stepper\")\n                .add(progressStep(\"step-1\", \"First step\")\n                        .ariaLabel(\"completed step, step with success\")\n                        .variant(success))\n                .add(progressStep(\"step-2\", \"Second step\")\n                        .ariaLabel(\"step with info\")\n                        .variant(info))\n                .add(progressStep(\"step-3\", \"Third step\")\n                        .ariaLabel(\"pending step\")\n                        .variant(pending))\n                .first().next())\n        .element()');
