  Code.f_snippets__org_patternfly_showcase_Code_.put('wizard-step-status', 'Wizard wizard = wizard();\nreturn div()\n        .add(wizard.height(400)\n                .addItem(wizardStep(\"wizard-step-status-step-0\", \"Step 1\")\n                        .add(p().text(\"Step 1 content\")))\n                .addItem(wizardStep(\"wizard-step-status-step-1\", \"Status step\")\n                        .add(radio(\"wizard-step-status-radio-error\", \"wizard-step-status-radio\",\n                                \"Give step 1 an error status\")\n                                .onChange((e, c, value) -> {\n                                    if (value) {\n                                        wizard.item(\"wizard-step-status-step-0\").status(error);\n                                    }\n                                }))\n                        .add(radio(\"wizard-step-status-radio-success\", \"wizard-step-status-radio\",\n                                \"Give step 1 a success status\")\n                                .onChange((e, c, value) -> {\n                                    if (value) {\n                                        wizard.item(\"wizard-step-status-step-0\").status(success);\n                                    }\n                                }))\n                )\n                .addItem(wizardStep(\"wizard-step-status-step-4\", \"Review\", review)\n                        .add(p().text(\"Review content\"))))\n        .element();');
  Code.f_snippets__org_patternfly_showcase_Code_.put('wizard-hap', '// ------------------------------------------------------ (n)ext (h)andler\n\nString nhId = \"wizard-hap-nh\";\nTextInput nhInput = textInput(number, nhId).value(\"2\");\nHelperText nhHelper = helperText(\"Enter an even number\");\nFormAlert nhAlert = formAlert().addAlert(alert(danger, \"Invalid number\")\n        .addDescription(\"Please enter an even number\"));\nForm nhForm = form()\n        .addGroup(formGroup(nhId)\n                .addLabel(formGroupLabel(\"Number\"))\n                .addControl(formGroupControl()\n                        .add(nhInput)\n                        .add(nhHelper)));\nWizardStepNextHandler nh = (wzd, current, next) -> {\n    boolean even = !nhInput.value().isEmpty() && Integer.parseInt(nhInput.value()) % 2 == 0;\n    if (even) {\n        nhForm.clearAlerts();\n        nhInput.resetValidation();\n        nhHelper.firstItem().status(default_);\n    } else {\n        if (!isAttached(nhAlert)) {\n            nhForm.addAlert(nhAlert);\n        }\n        nhInput.validated(error);\n        nhHelper.firstItem().status(error);\n    }\n    return even;\n};\n\n// ------------------------------------------------------ (p)revious (h)andler\n\nString phId = \"wizard-hap-ph\";\nTextInput phInput = textInput(number, phId).value(\"3\");\nHelperText phHelper = helperText(\"Enter an odd number\");\nFormAlert phAlert = formAlert().addAlert(alert(danger, \"Invalid number\")\n        .addDescription(\"Please enter an odd number\"));\nForm phForm = form()\n        .addGroup(formGroup(phId)\n                .addLabel(formGroupLabel(\"Number\"))\n                .addControl(formGroupControl()\n                        .add(phInput)\n                        .add(phHelper)));\nWizardStepPreviousHandler ph = (wzd, current, next) -> {\n    boolean odd = !phInput.value().isEmpty() && Integer.parseInt(phInput.value()) % 2 != 0;\n    if (odd) {\n        phForm.clearAlerts();\n        phInput.resetValidation();\n        phHelper.firstItem().status(default_);\n    } else {\n        if (!isAttached(phAlert)) {\n            phForm.addAlert(phAlert);\n        }\n        phInput.validated(error);\n        phHelper.firstItem().status(error);\n    }\n    return odd;\n};\n\n// ------------------------------------------------------ cooking steps\n\nString[] steps = new String[]{\n        \"Chopping the ingredients \uD83D\uDD2A\",\n        \"Heating up the pan \uD83D\uDD25\",\n        \"Throwing everything together \uD83C\uDF73\",\n        \"Letting it simmer for a bit \u23F3\",\n        \"Tasting and adjusting the seasoning \uD83D\uDE0B\",\n        \"Plating it nicely \uD83C\uDF7D\",\n        \"Dinner is served \u2705\"\n};\n\n// ------------------------------------------------------ (n)ext (p)romise\n\nint[] npIndex = new int[1];\ndouble[] npHandle = new double[1];\ndouble[] npInterval = new double[]{1200};\nSwitch npSwitch = switch_(\"wizard-hap-np\", \"wizard-hap-np\", true)\n        .label(\"Be a good chef.\");\nHTMLContainerBuilder<HTMLElement> npMs = span();\nSlider npSpeed = slider()\n        .value(npInterval[0])\n        .range(200, 2000, 200)\n        .showTicks(false)\n        .showBoundaries(false)\n        .onChange((e, c, value) -> {\n            npInterval[0] = value;\n            npMs.text(value + \" ms\");\n        });\nEmptyStateBody npBody = emptyStateBody();\nEmptyState npEmptyState = emptyState().size(xs).addBody(npBody);\nWizardStepEnterHandler npEnter = (wzd, step) -> {\n    npEmptyState.clearStatus().icon(utensils()).text(\"I\'m hungry\");\n    npBody.text(\"Think of your favorite meal and press \'Next\'.\");\n};\nWizardStepNextPromise np = (wzd, current, next) -> {\n    npIndex[0] = 0;\n    boolean success = npSwitch.value();\n    int end = success ? steps.length : 3 + (int) (Math.random() * (steps.length - 3));\n    npEmptyState.clearStatus().spinner().text(\"I\'m hungry.\");\n    return new Promise<>((resolve, reject) -> {\n        npHandle[0] = setInterval((__) -> {\n            npBody.text(steps[npIndex[0]++]);\n            if (npIndex[0] > end) {\n                clearInterval(npHandle[0]);\n                if (!success) {\n                    npEmptyState.status(danger).text(\"The chef failed\");\n                    npBody.text(\"Try again later.\");\n                }\n                resolve.onInvoke(success);\n            }\n        }, npInterval[0]);\n    });\n};\n\n// ------------------------------------------------------ (p)revious (p)romise\n\nint[] ppIndex = new int[1];\ndouble[] ppHandle = new double[1];\ndouble[] ppInterval = new double[]{1200};\nSwitch ppSwitch = switch_(\"wizard-hap-pp\", \"wizard-hap-pp\", true)\n        .label(\"Be a good chef.\");\nHTMLContainerBuilder<HTMLElement> ppMs = span();\nSlider ppSpeed = slider()\n        .value(npInterval[0])\n        .range(200, 2000, 200)\n        .showTicks(false)\n        .showBoundaries(false)\n        .onChange((e, c, value) -> {\n            ppInterval[0] = value;\n            ppMs.text(value + \" ms\");\n        });\nEmptyStateBody ppBody = emptyStateBody();\nEmptyState ppEmptyState = emptyState().size(xs).addBody(ppBody);\nWizardStepEnterHandler ppEnter = (wzd, step) -> {\n    ppEmptyState.clearStatus().icon(utensils()).text(\"I\'m hungry\");\n    ppBody.text(\"Think of your favorite meal and press \'Back\'.\");\n};\nWizardStepPreviousPromise pp = (wzd, current, next) -> {\n    ppIndex[0] = 0;\n    boolean success = ppSwitch.value();\n    int end = success ? steps.length : 3 + (int) (Math.random() * (steps.length - 3));\n    ppEmptyState.clearStatus().spinner().text(\"I\'m hungry.\");\n    return new Promise<>((resolve, reject) -> {\n        ppHandle[0] = setInterval((__) -> {\n            ppBody.text(steps[ppIndex[0]++]);\n            if (ppIndex[0] > end) {\n                clearInterval(ppHandle[0]);\n                if (!success) {\n                    ppEmptyState.status(danger).text(\"The chef failed\");\n                    ppBody.text(\"Try again later.\");\n                }\n                resolve.onInvoke(success);\n            }\n        }, ppInterval[0]);\n    });\n};\n\n// ------------------------------------------------------ enter and leave handlers\n\nDateTimeFormat dtf = dateTimeFormat(navigator.language, dateTimeFormatOptions().timeStyle(medium));\nHTMLContainerBuilder<HTMLElement> ehTime = strong(\"n/a\");\nWizardStepEnterHandler eh = (wzd, step) -> ehTime.text(dtf.format(new JsDate()));\nHTMLContainerBuilder<HTMLElement> lhTime = strong(\"n/a\");\nWizardStepLeaveHandler lh = (wzd, step) -> lhTime.text(dtf.format(new JsDate()));\n\n// ------------------------------------------------------ wizard and step components\n\nreturn div()\n        .add(wizard().height(450)\n                .onStepChange((wzd, previous, current) -> {\n                    if (previous == null) {\n                        console.log(\"Step changed to \'%s\'\", current.identifier());\n                    } else {\n                        console.log(\"Step changed from \'%s\' to \'%s\'\",\n                                previous.identifier(), current.identifier());\n                    }\n                })\n                .addItem(wizardStep(\"wizard-hap-step-nh\", \"Next handler\")\n                        .add(content(p).editorial()\n                                .add(\"This step has a \")\n                                .add(Elements.code(\"WizardStepNextHandler\"))\n                                .add(\" that returns \")\n                                .add(Elements.code(\"true\"))\n                                .add(\" if the number is even.\"))\n                        .add(content(p).editorial()\n                                .add(\"This prevents a next step from being executed as long as the number is not even.\"))\n                        .add(nhForm)\n                        .nextIf(nh))\n                .addItem(wizardStep(\"wizard-hap-step-np\", \"Next promise\")\n                        .add(flex().direction(column).gap(md)\n                                .addItem(flexItem()\n                                        .add(content(p).editorial()\n                                                .add(\"This step has a \")\n                                                .add(Elements.code(\"WizardStepNextPromise\"))\n                                                .add(\" that simulates cooking a meal and you can decide whether you get something to eat or not.\"))\n                                        .add(flex().direction(row).gap(md).alignItems(center)\n                                                .addItem(flexItem().add(npSwitch))\n                                                .addItem(flexItem().flex(_1)\n                                                        .add(flex().direction(row).gap(sm).alignItems(center)\n                                                                .addItem(flexItem().add(\"Cooking speed: \"))\n                                                                .addItem(flexItem().flex(_1).add(npSpeed))\n                                                                .addItem(flexItem().add(npMs))))))\n                                .addItem(flexItem().add(npEmptyState)))\n                        .onEnter(npEnter)\n                        .nextIfPromised(np))\n                .addItem(wizardStep(\"wizard-hap-step-ph\", \"Previous handler\")\n                        .add(content(p).editorial()\n                                .add(\"This step has a \")\n                                .add(Elements.code(\"WizardStepPreviousHandler\"))\n                                .add(\" that returns \")\n                                .add(Elements.code(\"true\"))\n                                .add(\" if the number is odd.\"))\n                        .add(content(p).editorial()\n                                .add(\"This prevents a previous step from being executed as long as the number is not odd.\"))\n                        .add(phForm)\n                        .previousIf(ph))\n                .addItem(wizardStep(\"wizard-hap-step-pp\", \"Previous promise\")\n                        .add(flex().direction(column).gap(md)\n                                .addItem(flexItem()\n                                        .add(content(p).editorial()\n                                                .add(\"This step has a \")\n                                                .add(Elements.code(\"WizardStepPreviousPromise\"))\n                                                .add(\" that simulates cooking a meal and you can decide whether you get something to eat or not.\"))\n                                        .add(flex().direction(row).gap(md).alignItems(center)\n                                                .addItem(flexItem().add(ppSwitch))\n                                                .addItem(flexItem().flex(_1)\n                                                        .add(flex().direction(row).gap(sm).alignItems(center)\n                                                                .addItem(flexItem().add(\"Cooking speed: \"))\n                                                                .addItem(flexItem().flex(_1).add(ppSpeed))\n                                                                .addItem(flexItem().add(ppMs))))))\n                                .addItem(flexItem().add(ppEmptyState)))\n                        .onEnter(ppEnter)\n                        .previousIfPromised(pp))\n                .addItem(wizardStep(\"wizard-hap-step-eh\", \"Enter handler\")\n                        .add(content(p).editorial()\n                                .add(\"This step has a \")\n                                .add(Elements.code(\"WizardStepEnterHandler\"))\n                                .add(\" that logs the time when you\'ve entered this step.\"))\n                        .add(content(p).editorial()\n                                .add(\"Step entered at \")\n                                .add(ehTime))\n                        .onEnter(eh))\n                .addItem(wizardStep(\"wizard-hap-step-lh\", \"Leave handler\")\n                        .add(content(p).editorial()\n                                .add(\"This step has a \")\n                                .add(Elements.code(\"WizardStepLeaveHandler\"))\n                                .add(\" that logs the time when you\'ve left this step.\"))\n                        .add(content(p).editorial()\n                                .add(\"Step left at \")\n                                .add(lhTime))\n                        .onLeave(lh))\n                .addItem(wizardStep(\"wizard-hap-step-rvw\", \"Review\", review)\n                        .add(bullseye().addItem(bullseyeItem().add(emptyState().size(xs)\n                                .icon(cakeCandles())\n                                .text(\"Congratulations!\")\n                                .addBody(emptyStateBody().add(content(p).editorial()\n                                        .text(\"You have successfully completed all steps.\"))))))))\n        .element();');
  Code.f_snippets__org_patternfly_showcase_Code_.put('finder-basic', '// Declare the functions as final arrays here so that they can call each other\nfinal Function<FileData, FinderItem>[] fileItem = new Function[1];\nfinal Function<FileData, FinderColumn>[] fileColumn = new Function[1];\n\nFunction<String, FinderColumnHeader> demoHeader = text -> finderColumnHeader(text)\n        .addActions(finderColumnActions()\n                .addButton(button(plus()).plain())\n                .addButton(button(redo()).plain())\n                .addDropdown(mixedKebab(Id.build(\"finder-basic\", text, \"ca\"))));\n\nfileColumn[0] = file -> finderColumn(file.id)\n        .addHeader(demoHeader.apply(file.name))\n        .run(column -> {\n            if (file.children != null) {\n                column.addItems(file.children.asList(), fileItem[0]);\n            }\n        });\n\nfileItem[0] = file -> finderItem(file.id, file.name)\n        .icon(predefinedIcon(file.icon))\n        .run(item -> {\n            if (file.description != null) {\n                item.addDescription(file.description);\n            }\n            if (file.actions != null) {\n                item.addActions(file.itemActions());\n            }\n            if (file.children != null) {\n                item.nextColumn(() -> fileColumn[0].apply(file));\n            }\n        });\n\nreturn finder().bordered()\n        .addItem(finderColumn(\"root\").run(column -> column\n                .addHeader(demoHeader.apply(\"Root\"))\n                .defaultSearch()\n                .addItems(Files.data.asList(), fileItem[0])))\n        .element();');
  Code.f_snippets__org_patternfly_showcase_Code_.put('finder-preview', 'finder().bordered()\n        .addItem(finderColumn(\"root\")\n                .addHeader(finderColumnHeader(\"Root\"))\n                .addItems(Files.data.asList(), file -> finderItem(file.id, file.name)\n                        .icon(predefinedIcon(file.icon))\n                        .store(\"file\", file)\n                        .run(item -> {\n                            if (file.description != null) {\n                                item.addDescription(file.description);\n                            }\n                        }))\n                .onPreview((item, preview) -> {\n                    FileData file = item.get(\"file\");\n                    preview.add(content(h1)\n                            .add(icon(predefinedIcon(file.icon)).inline())\n                            .add(\" \" + file.name));\n                    if (file.description != null) {\n                        preview.add(content(p).editorial().text(file.description));\n                    }\n                    if (file.meta != null) {\n                        preview.add(descriptionList().run(dl -> file.meta.forEach(key ->\n                                dl.addItem(descriptionListGroup(Id.unique(\"finder-preview\", key))\n                                        .addTerm(descriptionListTerm(key))\n                                        .addDescription(descriptionListDescription(file.meta.get(key)))))));\n                    }\n                }))\n        .addPreview(finderPreview()\n                .add(content(h1).text(\"Preview\"))\n                .add(content(p).editorial().text(\"Please select an item to see the preview.\")))\n        .element()');
  Code.f_snippets__org_patternfly_showcase_Code_.put('finder-async', 'int[][] decades = new int[][]{\n        new int[]{1970, 1979},\n        new int[]{1980, 1989},\n        new int[]{1990, 1999},\n        new int[]{2000, 2009},\n        new int[]{2010, 2019},\n        new int[]{2020, 2029},\n        new int[]{2030, 2039},\n};\n\nPreviewHandler recordPreview = (item, preview) -> {\n    Record record = item.get(\"record\");\n    preview.add(content(h1).text(record.title))\n            .add(content(p).editorial().text(\"Released \" + record.released))\n            .add(div().add(img(record.cover)))\n            .add(content(p)\n                    .add(\"More infos: \")\n                    .add(a(record.url, \"_blank\").text(record.url)));\n};\nPreviewHandler trackPreview = (item, preview) -> {\n    Track track = item.get(\"track\");\n    preview.add(content(h1).text(track.title))\n            .add(descriptionList().horizontal().css(util(\"mt-sm\"))\n                    .addItem(descriptionListGroup()\n                            .addTerm(descriptionListTerm(\"Title\"))\n                            .addDescription(descriptionListDescription(track.title)))\n                    .addItem(descriptionListGroup()\n                            .addTerm(descriptionListTerm(\"Length\"))\n                            .addDescription(descriptionListDescription(track.length)))\n                    .run(dl -> {\n                        if (track.writer != null) {\n                            dl.addItem(descriptionListGroup()\n                                    .addTerm(descriptionListTerm(\"Writer\"))\n                                    .addDescription(descriptionListDescription(String.join(\", \", track.writer()))));\n                        }\n                    }));\n};\n\nFunction<Record, FinderItem> recordItem = record -> finderItem(Id.build(record.title))\n        .text(record.title)\n        .addDescription(String.valueOf(record.year))\n        .icon(recordVinyl())\n        .store(\"record\", record)\n        .nextColumn(() -> finderColumn(Id.build(record.title))\n                .addHeader(finderColumnHeader(record.title))\n                .addItems(record.tracks.asList(), track ->\n                        finderItem(Id.build(record.title, String.valueOf(track.track)))\n                                .text(track.track + \". \" + track.title)\n                                .icon(music())\n                                .store(\"track\", track))\n                .onPreview(trackPreview));\n\nFunction<int[], FinderColumn> decadeColumn = decade -> finderColumn(\n        Id.build(String.valueOf(decade[0]), String.valueOf(decade[1])))\n        .run(column -> column.addHeader(finderColumnHeader(decade[0] + \" - \" + decade[1])\n                .addActions(finderColumnActions()\n                        .addButton(button(redo()).plain()\n                                .onClick((e, b) -> column.reload())))))\n        .addItems(item -> new Promise<>((resolve, reject) -> {\n            boolean boom = Math.random() < 0.25; // simulate error\n            int delay = new Random().nextInt(2000); // simulate remote call\n            setTimeout(__ -> {\n                if (boom) {\n                    reject.onInvoke(\"Random error\");\n                } else {\n                    List<FinderItem> items = records(r -> r.year >= decade[0] && r.year <= decade[1])\n                            .stream()\n                            .map(recordItem)\n                            .collect(toList());\n                    if (items.isEmpty()) {\n                        resolve.onInvoke(singletonList(emptyItem(emptyState()\n                                .size(xs)\n                                .text(\"No records\")\n                                .icon(ban())\n                                .addBody(emptyStateBody().text(\"No records have been released in this decade.\")))));\n                    } else {\n                        resolve.onInvoke(items);\n                    }\n                }\n            }, delay);\n        }))\n        .onPreview(recordPreview);\n\nreturn finder().bordered().style(\"height: 500px;\")\n        .addItem(finderColumn(\"Decades\")\n                .addHeader(finderColumnHeader(\"Decades\"))\n                .addItems(asList(decades),\n                        decade -> finderItem(Id.build(String.valueOf(decade[0]), String.valueOf(decade[1])))\n                                .text(decade[0] + \" - \" + decade[1])\n                                .icon(folder())\n                                .nextColumn(() -> decadeColumn.apply(decade))))\n        .addPreview(finderPreview())\n        .element();');
